check('independent-full-runtime-literal-oracles',()=>{
  const g=policy.runtimeGovernance, schemas=policy.runtimeObjectSchemas;
  const oracle=LITERAL_ORACLE;
  assert.deepEqual(policy.routePolicy,oracle.routePolicy,'RoutePolicy independent literal drift');
  assert.deepEqual(policy.futureTopology,oracle.futureTopology,'FutureTopology independent literal drift');
  assert.deepEqual(g.terminalClassifierExactOrdered,oracle.terminalClassifier,'Classifier13 independent literal drift');
  assert.equal(oracle.terminalClassifier.length,ORACLE_META.terminalClassifier.count);
  assert.deepEqual(g.terminalScienceLockProjectionExactByArm,oracle.scienceLocks,'Science6 independent literal drift');
  assert.equal(oracle.scienceLocks.length,ORACLE_META.scienceLocks.count);
  assert.deepEqual(g.canonicalRuntimeCapsExact,oracle.runtimeCaps,'Caps23 independent literal drift');
  assert.equal(Object.keys(oracle.runtimeCaps).length,ORACLE_META.runtimeCaps.count);
  assert.deepEqual(g.capabilityProbeIdsExact,oracle.probeIds,'ProbeIds independent literal drift');
  assert.deepEqual(g.capabilityProbePolicyRowsExactOrdered,oracle.probeRows,'ProbeRows independent literal drift');
  assert.deepEqual(g.failureToTerminalBranchExactOrdered,oracle.failureToTerminal,'Failure13 independent literal drift');
  assert.deepEqual(g.terminalArmEventStateProjectionExact,oracle.terminalProjection,'TerminalProjection6 independent literal drift');
  assert.deepEqual(schemas.find(x=>x.schemaId==='tag926-terminal-event/v1'),oracle.tag926EventSchema,'Tag926 Event schema/rules literal drift');
  assert.deepEqual(schemas.find(x=>x.schemaId==='route-public-state/v1'),oracle.routePublicStateSchema,'Tag926 State schema/rules literal drift');
  for(const [key,value] of Object.entries(ORACLE_RULES)) assert.equal(g[key],value,`${key}: independent rule drift`);

  const schemaIds=schemas.map(x=>x.schemaId);
  const numericEdges=strictJson(Buffer.from(g.schemaReferenceFieldCatalogCanonicalUtf8Base64,'base64').toString('utf8'));
  const semanticEdges=numericEdges.map(([sourceIndex,fieldIndex,targetIndex,kind,cardinality,branchMask])=>[
    schemaIds[sourceIndex],schemas[sourceIndex].exactKeys[fieldIndex],targetIndex===-1?null:schemaIds[targetIndex],
    ['OBJECT_SCHEMA','EXTERNAL_CONTENT_ADDRESSED_ARTIFACT','SELF_HASH'][kind],
    ['EXACT_ONE','OPTIONAL_ONE','ORDERED_OR_KEYED_MANY'][cardinality],branchMask,
  ]);
  assert.equal(semanticEdges.length,ORACLE_META.referenceEdges.count);
  assert.deepEqual(semanticEdges,oracle.referenceEdges,'774 exact semantic edge tuples drift');
  assert.equal(g.schemaReferenceGraphEdgeCount,ORACLE_META.referenceEdges.count);

  const timeUniverse=strictJson(Buffer.from(g.timestampFieldUniverseCanonicalUtf8Base64,'base64').toString('utf8'));
  const timeCatalog=strictJson(Buffer.from(g.branchTimestampCoverageCatalogCanonicalUtf8Base64,'base64').toString('utf8'));
  assert.deepEqual({branchTimestampCoverageCatalog:timeCatalog,timestampFieldUniverse:timeUniverse},oracle.branchTimeProofs,'16-branch time oracle drift');
  assert.equal(timeUniverse.length,ORACLE_META.branchTimeProofs.universeCount);
  assert.equal(timeCatalog.branchRows.length,ORACLE_META.branchTimeProofs.count);

  const roleProjection={
    expectedClosureSetsExact:g.schemaReachabilityExpectedClosureSetsExact,
    roleCatalogExact:g.schemaReachabilityRoleCatalogExact,
    topLevelRootsExact:g.schemaReferenceRoleRootsExact,
  };
  assert.deepEqual(roleProjection,oracle.roleRootsAndClosures,'Role -> true roots -> closures independent literal drift');
  assert.equal(Object.values(g.schemaReferenceRoleRootsExact).flat().length,ORACLE_META.roleRootsAndClosures.rootCount);
  assert.deepEqual(Object.values(g.schemaReachabilityRoleCatalogExact).map(x=>x.length),[24,95,3,1,11]);
});

