check('independent-oracle-coherent-builder4-rehash-fixtures',()=>{
  const fixtures=[
    {id:'ORACLE_ROUTE_SUCCESS_THRESHOLD',mutate:p=>{p.routePolicy.catalogSuccessIff=p.routePolicy.catalogSuccessIff.replaceAll('GTE_2','GTE_1');}},
    {id:'ORACLE_FUTURE_PARENT_ROLE',mutate:p=>{p.futureTopology.tag925.directParentRole='TAG923_REMOTE_CONFIRMED';}},
    {id:'ORACLE_EDGE_CARDINALITY',mutate:p=>{const g=p.runtimeGovernance,rows=strictJson(Buffer.from(g.schemaReferenceFieldCatalogCanonicalUtf8Base64,'base64').toString('utf8'));rows[0][4]=rows[0][4]===0?1:0;setPinnedCanonical(g,'schemaReferenceFieldCatalog',rows);g.schemaReferenceGraphCanonicalSha256=g.schemaReferenceFieldCatalogSha256;}},
    {id:'ORACLE_TIME_OPERATOR',mutate:p=>{const g=p.runtimeGovernance,proof=strictJson(Buffer.from(g.branchTimestampCoverageCatalogCanonicalUtf8Base64,'base64').toString('utf8')),edge=proof.branchRows.find(x=>x.causalEdgesRecordedIndexPairsWithOperatorCode0Lt1Lte.length).causalEdgesRecordedIndexPairsWithOperatorCode0Lt1Lte[0];edge[2]=edge[2]===1?0:1;setPinnedCanonical(g,'branchTimestampCoverageCatalog',proof);}},
    {id:'ORACLE_ROLE_ROOT_ORDER',mutate:p=>{const g=p.runtimeGovernance,roots=g.schemaReferenceRoleRootsExact.TAG925_PRESTART_AUTHORITY;[roots[0],roots[1]]=[roots[1],roots[0]];const numeric=strictJson(Buffer.from(g.schemaReferenceRootPointerCatalogCanonicalUtf8Base64,'base64').toString('utf8'));const a=numeric.find(x=>x[0]===0&&x[1]===0),b=numeric.find(x=>x[0]===0&&x[1]===1);[a[2],b[2]]=[b[2],a[2]];setPinnedCanonical(g,'schemaReferenceRootPointerCatalog',numeric);setPinnedCanonical(g,'schemaReachabilityOracle',roleSemanticProjection(p));}},
    {id:'ORACLE_CLASSIFIER_CONDITION',mutate:p=>{p.runtimeGovernance.terminalClassifierExactOrdered[10].condition=p.runtimeGovernance.terminalClassifierExactOrdered[10].condition.replace('GTE2','GTE1');}},
    {id:'ORACLE_SCIENCE_CREDIT',mutate:p=>{p.runtimeGovernance.terminalScienceLockProjectionExactByArm[0].scientificCredit='SOME';}},
    {id:'ORACLE_CAP_CERT_COUNT',mutate:p=>{p.runtimeGovernance.canonicalRuntimeCapsExact.tlsCertificateCountMaximum=17;}},
    {id:'ORACLE_PROBE_PASS_PREDICATE',mutate:p=>{p.runtimeGovernance.capabilityProbePolicyRowsExactOrdered[0].passIffExact+='OR_TRUE';}},
    {id:'ORACLE_FAILURE_ARM',mutate:p=>{p.runtimeGovernance.failureToTerminalBranchExactOrdered[0].terminalBranchKind='NORMAL_SUCCESS_OR_LOCAL_HOLDS';}},
    {id:'ORACLE_TERMINAL_PROJECTION',mutate:p=>{p.runtimeGovernance.terminalArmEventStateProjectionExact[0]=p.runtimeGovernance.terminalArmEventStateProjectionExact[0].replace('TRUE_IFF','TRUE_ALWAYS_IGNORING_IFF');}},
    {id:'ORACLE_EVENT_STATE_SCHEMA_RULE',mutate:p=>{p.runtimeObjectSchemas.find(x=>x.schemaId==='tag926-terminal-event/v1').rules+='ALLOW_HOLD_NEXT_TRUE';}},
  ];
  const ids=new Set(), results={planned:fixtures.length,executed:0,rejected:0};
  for(const spec of fixtures){
    assert(!ids.has(spec.id),`duplicate coherent fixture id ${spec.id}`); ids.add(spec.id);
    const fixture=coherentBuilder4Fixture(spec.id,spec.mutate); results.executed+=1;
    assert.notEqual(sha256(fixture.contractRaw),sha256(contractRaw),`${spec.id}: contract was not rehashed`);
    assert.notEqual(sha256(fixture.controllerRaw),sha256(controllerRaw),`${spec.id}: controller was not rehashed`);
    assert.notEqual(sha256(fixture.eventRaw),sha256(eventRaw),`${spec.id}: event was not rehashed`);
    assert.notEqual(sha256(fixture.stateRaw),sha256(stateRaw),`${spec.id}: state was not rehashed`);
    assert.throws(()=>assertIndependentRuntimeLiteralOracles(fixture.contract.staticPolicy),assert.AssertionError,`${spec.id}: independent literal oracle survived coherent rehash`);
    results.rejected+=1;
  }
  assert.deepEqual(results,{planned:12,executed:12,rejected:12});
});

